    return {
      xu: (FX(u + h, v) - FX(u - h, v)) / (2 * h),
      yu: (FY(u + h, v) - FY(u - h, v)) / (2 * h),
      xv: (FX(u, v + h) - FX(u, v + h - 2 * h)) / (2 * h) * 0 + (FX(u, v + h) - FX(u, v - h)) / (2 * h),
      yv: (FY(u, v + h) - FY(u, v - h)) / (2 * h)
    };
  }

  // ---------- left panel ----------
  function drawLeft() {
    var g = gLeft;
    var u0 = st.u0, v0 = st.v0, du = st.du, dv = st.dv;
    var eu = Math.max(0.22, 0.35 * du), ev = Math.max(0.22, 0.35 * dv);
    eu = Math.min(eu, u0 - 0.06, 2.9 - (u0 + du));
    ev = Math.min(ev, v0 - 0.06, 2.95 - (v0 + dv));

    // axes
    g.line(26, OY, 412, OY).stroke({ color: '#000', width: 2 });
    arrowHead(g, 424, OY, 0, 13, '#000');
    g.line(OX, 344, OX, 40).stroke({ color: '#000', width: 2 });
    arrowHead(g, OX, 28, -Math.PI / 2, 13, '#000');
    txt(g, 'u', 396, OY - 12, 18, { anchor: 'middle' });
    txt(g, 'v', OX + 14, 42, 18, { anchor: 'middle' });

    var lx = UX(u0), rx = UX(u0 + du), by = VY(v0), ty = VY(v0 + dv);
    var lineTop = VY(v0 + dv + ev), lineBot = VY(v0 - ev);
    var lineL = UX(u0 - eu), lineR = UX(u0 + du + eu);

    // blue coordinate lines
    [lx, rx].forEach(function (x) { g.line(x, lineBot, x, lineTop).stroke({ color: BLUE, width: 3.2, linecap: 'round' }); });
    [by, ty].forEach(function (y) { g.line(lineL, y, lineR, y).stroke({ color: BLUE, width: 3.2, linecap: 'round' }); });

    // rectangle S
    var rect = g.rect(rx - lx, by - ty).move(lx, ty).fill({ color: FILL, opacity: 0.95 })
      .stroke({ color: BLUE, width: 2 }).css('cursor', 'pointer');
    rect.on('mousemove', function (e) { showTooltip('S : the rectangle [u₀, u₀+Δu] × [v₀, v₀+Δv], area = ΔuΔv', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The rectangle S', 'In the uv-plane the region is a plain rectangle of area Δu·Δv = ' +
          fmt(st.du * st.dv) + '. Integrating over such a rectangle is easy — that is the whole reason for changing variables.');
      });

    txt(g, 'S', (lx + rx) / 2, (ty + by) / 2 + 7, 20, { anchor: 'middle', weight: 'bold' });

    // corner dots
    [[lx, by], [rx, by], [lx, ty], [rx, ty]].forEach(function (c) {
      g.circle(9).center(c[0], c[1]).fill(BLUE).stroke({ color: '#fff', width: 1 });
    });
    var hLL = g.circle(15).center(lx, by).fill(BLUE).stroke({ color: '#fff', width: 2 }).css('cursor', 'move');
    var hUR = g.circle(15).center(rx, ty).fill(BLUE).stroke({ color: '#fff', width: 2 }).css('cursor', 'nwse-resize');
    hLL.on('mousemove', function (e) { showTooltip('Drag: move S (changes u₀, v₀)', e); }).on('mouseleave', hideTooltip);
    hUR.on('mousemove', function (e) { showTooltip('Drag: resize S (changes Δu, Δv)', e); }).on('mouseleave', hideTooltip);
    hLL.on('mousedown', function (e) { e.preventDefault(); dragMode = 'll'; });
    hUR.on('mousedown', function (e) { e.preventDefault(); dragMode = 'ur'; });

    // labels
    if (rx - lx >= 115) {
      txt(g, 'u = u₀', lx, lineTop - 11, 16, { anchor: 'middle' });
      txt(g, 'u = u₀ + Δu', rx, lineTop - 11, 16, { anchor: 'middle' });
    } else {
      txt(g, 'u = u₀', lx - 5, lineTop - 11, 16, { anchor: 'end' });
      txt(g, 'u = u₀ + Δu', rx + 5, lineTop - 11, 16, { anchor: 'start' });
    }
    txt(g, 'v = v₀ + Δv', lineR + 9, ty + 5, 16, { anchor: 'start' });
    txt(g, 'v = v₀', lineR + 9, by + 5, 16, { anchor: 'start' });
    var cornerX = lx - 12 - (rx - lx < 70 ? 26 : 0);
    txt(g, '(u₀, v₀)', cornerX, by + 26, 16, { anchor: 'end' });
    txt(g, 'Δu', (lx + rx) / 2, by + 24, 16, { anchor: 'middle' });
    txt(g, 'Δv', rx + 9, (ty + by) / 2 + 6, 16, { anchor: 'start' });
  }

  // ---------- right panel ----------
  function drawRight() {
    var g = gRight;
    var u0 = st.u0, v0 = st.v0, du = st.du, dv = st.dv;
    var eu = 0.35 * du, ev = 0.35 * dv, N = 70;

    var cU0 = curvePts(true, u0, v0 - ev, v0 + dv + ev, N);
    var cU1 = curvePts(true, u0 + du, v0 - ev, v0 + dv + ev, N);
    var cV0 = curvePts(false, v0, u0 - eu, u0 + du + eu, N);
    var cV1 = curvePts(false, v0 + dv, u0 - eu, u0 + du + eu, N);
    var reg = regionPts(34);

    var all = cU0.concat(cU1, cV0, cV1, [[0, 0]]);
    if (all.length < 5 || reg.length < 6) {
      txt(g, 'T is undefined on this rectangle', 683, 170, 16, { anchor: 'middle', style: 'normal', fill: '#c00' });
      return null;
    }
    var minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    all.forEach(function (p) {
      if (p[0] < minX) minX = p[0]; if (p[0] > maxX) maxX = p[0];
      if (p[1] < minY) minY = p[1]; if (p[1] > maxY) maxY = p[1];
    });
    var bw = Math.max(maxX - minX, 1e-3), bh = Math.max(maxY - minY, 1e-3);
    bw *= 1.14; bh *= 1.14;
    var X0 = 535, X1 = 832, Y0 = 52, Y1 = 286;
    var s = Math.min((X1 - X0) / bw, (Y1 - Y0) / bh);
    var mx = (minX + maxX) / 2, my = (minY + maxY) / 2;
    var cx = (X0 + X1) / 2, cy = (Y0 + Y1) / 2;
    function PX(x) { return cx + (x - mx) * s; }
    function PY(y) { return cy - (y - my) * s; }

    // axes
    var ax = clamp(PY(0), Y0 - 6, Y1 + 40), ay = clamp(PX(0), X0 - 6, X1 + 40);
    g.line(526, ax, 898, ax).stroke({ color: '#000', width: 2 });
    arrowHead(g, 910, ax, 0, 13, '#000');
    g.line(ay, Math.min(ax + 52, 348), ay, 44).stroke({ color: '#000', width: 2 });
    arrowHead(g, ay, 32, -Math.PI / 2, 13, '#000');
    txt(g, 'x', 878, ax - 13, 18, { anchor: 'middle' });
    txt(g, 'y', ay + 14, 46, 18, { anchor: 'middle' });

    // region R
    var scr = reg.map(function (p) { return [PX(p[0]), PY(p[1])]; });
    var poly = g.polygon(pstr(scr)).fill({ color: FILL, opacity: 0.95 }).stroke('none').css('cursor', 'pointer');
    var trueArea = shoelace(reg);
    poly.on('mousemove', function (e) { showTooltip('R = T(S), true area ≈ ' + fmt(trueArea), e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The image region R', 'R = T(S) is bounded by four coordinate curves. Its area is ' + fmt(trueArea) +
          ', while S has area ' + fmt(st.du * st.dv) + '. The ratio is the local area-stretching factor — the Jacobian.');
      });

    // boundary curves
    [cU0, cU1, cV0, cV1].forEach(function (c) {
      g.polyline(pstr(c.map(function (p) { return [PX(p[0]), PY(p[1])]; })))
        .fill('none').stroke({ color: BLUE, width: 3.4, linecap: 'round', linejoin: 'round' });
    });

    var ccx = 0, ccy = 0;
    scr.forEach(function (p) { ccx += p[0]; ccy += p[1]; });
    ccx /= scr.length; ccy /= scr.length;
    txt(g, 'R', ccx, ccy + 7, 20, { anchor: 'middle', weight: 'bold' });

    // curve labels with leaders
    function label(text, curve, tx, ty, anchor) {
      var w = wEst(text, 14);
      var lead = anchor === 'end' ? [tx - w - 8, ty - 3] : [tx + w / 2, ty + 9];
      var best = null, bd = Infinity;
      curve.forEach(function (p) {
        var X = PX(p[0]), Y = PY(p[1]);
        var d = (X - lead[0]) * (X - lead[0]) + (Y - lead[1]) * (Y - lead[1]);
        if (d < bd) { bd = d; best = [X, Y]; }
      });
      if (best && bd > 260) g.line(lead[0], lead[1], best[0], best[1]).stroke({ color: '#777', width: 1 });
      txt(g, text, tx, ty, 14, { anchor: anchor, style: 'normal' });
    }
    label('Image of u = u₀', cU0, 534, 72, 'start');
    label('Image of u = u₀ + Δu', cU1, 992, 40, 'end');
    label('Image of v = v₀ + Δv', cV1, 992, 124, 'end');
    label('Image of v = v₀', cV0, 992, 216, 'end');

    // Jacobian / tangent parallelogram
    var d = partials(u0, v0);
    var J = d.xu * d.yv - d.xv * d.yu;
    var P = mapPt(u0, v0);
    if (st.overlay && isFinite(J) && isFinite(P[0]) && isFinite(P[1])) {
      var A = [d.xu * du, d.yu * du], B = [d.xv * dv, d.yv * dv];
      var p0 = [PX(P[0]), PY(P[1])];
      var pA = [PX(P[0] + A[0]), PY(P[1] + A[1])];
      var pB = [PX(P[0] + B[0]), PY(P[1] + B[1])];
      var pAB = [PX(P[0] + A[0] + B[0]), PY(P[1] + A[1] + B[1])];
      var par = g.polygon(pstr([p0, pA, pAB, pB])).fill({ color: ORANGE, opacity: 0.12 })
        .stroke({ color: ORANGE, width: 1.8, linejoin: 'round' }).attr('stroke-dasharray', '6,4').css('cursor', 'pointer');
      par.on('mousemove', function (e) { showTooltip('Tangent parallelogram: area = |J| ΔuΔv = ' + fmt(Math.abs(J) * du * dv), e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Linear approximation', 'Near (u₀,v₀), T behaves like its derivative: the edges of S map to the vectors r_uΔu and r_vΔv. The parallelogram they span has area |∂(x,y)/∂(u,v)|·ΔuΔv, and it matches area(R) ever more exactly as Δu, Δv → 0.');
        });
      vecArrow(g, p0[0], p0[1], pA[0], pA[1], ORANGE, 2.4);
      vecArrow(g, p0[0], p0[1], pB[0], pB[1], ORANGE, 2.4);
      g.circle(8).center(p0[0], p0[1]).fill(ORANGE);
      txt(g, 'r_u Δu', pA[0] + 6 * Math.sign(pA[0] - p0[0] || 1), pA[1] + 16, 13, { anchor: 'middle', fill: ORANGE });
      txt(g, 'r_v Δv', pB[0] + 6 * Math.sign(pB[0] - p0[0] || 1), pB[1] - 8, 13, { anchor: 'middle', fill: ORANGE });

      // readout box
      var bx = 662, by2 = 300;
      g.rect(328, 54).move(bx, by2).fill('#ffffff').stroke({ color: '#c9ced4', width: 1 }).radius(4);
      var mono = { family: 'ui-monospace, Consolas, monospace', style: 'normal', halo: 0 };
      txt(g, 'Δu·Δv = ' + fmt(du * dv) + '        |J(u₀,v₀)| = ' + fmt(Math.abs(J)), bx + 10, by2 + 19, 12, mono);
      txt(g, '|J|·Δu·Δv = ' + fmt(Math.abs(J) * du * dv), bx + 10, by2 + 35, 12, mono);
      txt(g, 'true area(R) = ' + fmt(trueArea) + '   ratio = ' + fmt(Math.abs(J) * du * dv / (trueArea || NaN)),
        bx + 10, by2 + 49, 12, mono);
    }
    return { J: J, trueArea: trueArea };
  }

  // ---------- render ----------
  function render() {
    if (!FX || !FY) return;
    gLeft.clear(); gRight.clear();
    drawLeft();
    var stats = drawRight();
    var el = document.getElementById('readout');
    if (el) {
      if (!stats) { el.innerHTML = 'T is undefined on this rectangle.'; }
      else {
        var a0 = st.du * st.dv, aJ = Math.abs(stats.J) * a0;
        el.innerHTML = 'Δu·Δv = ' + fmt(a0) + '<br>|J(u₀,v₀)| = ' + fmt(Math.abs(stats.J)) +
          '<br>|J|·Δu·Δv = ' + fmt(aJ) + '<br>area(R) = ' + fmt(stats.trueArea) +
          '<br>ratio = ' + fmt(aJ / (stats.trueArea || NaN));
      }
    }
  }

  // ---------- interactions ----------
  window.update_shrinkRectangle = function (v) {
    st.du = v; st.dv = v;
    if (st.u0 + st.du > MAXU) st.u0 = MAXU - st.du;
    if (st.v0 + st.dv > MAXV) st.v0 = MAXV - st.dv;
    st.u0 = clamp(st.u0, 0.12, MAXU - st.du);
    st.v0 = clamp(st.v0, 0.12, MAXV - st.dv);
    render();
  };
  window.toggle_showParallelogram = function (on) { st.overlay = !!on; render(); };
  window.preset = function (a, b) {
    var xi = document.getElementById('xuvInput'), yi = document.getElementById('yuvInput');
    xi.value = a; xi.dispatchEvent(new Event('input'));
    yi.value = b; yi.dispatchEvent(new Event('input'));
  };

  // dragging
  var dragMode = null;
  function toUser(ev) {
    var pt = draw.node.createSVGPoint();
    pt.x = ev.clientX; pt.y = ev.clientY;
    var m = draw.node.getScreenCTM();
    if (!m) return null;
    return pt.matrixTransform(m.inverse());
  }
  document.addEventListener('mousemove', function (ev) {
    if (!dragMode) return;
    var p = toUser(ev); if (!p) return;
    var u = (p.x - OX) / SU, v = (OY - p.y) / SU;
    if (dragMode === 'll') {
      st.u0 = clamp(u, 0.12, MAXU - st.du);
      st.v0 = clamp(v, 0.12, MAXV - st.dv);
    } else {
      st.du = clamp(u - st.u0, 0.05, MAXU - st.u0);
      st.dv = clamp(v - st.v0, 0.05, MAXV - st.v0);
      var sl = document.getElementById('shrinkRectangleInput');
      sl.value = clamp(st.du, 0.05, 1.2).toFixed(2);
      document.getElementById('shrinkRectangleVal').value = (+sl.value).toFixed(2);
    }
    render();
  });
  document.addEventListener('mouseup', function () { dragMode = null; });

  // ---------- equations ----------
  bindEquationInput('xuvInput', function (fn) { FX = fn; render(); }, { variables: ['u', 'v'] });
  bindEquationInput('yuvInput', function (fn) { FY = fn; render(); }, { variables: ['u', 'v'] });

  // ---------- demo steps ----------
  var steps = [
    { t: 'The rectangle S in the uv-plane',
      n: 'On the left, the coordinate lines u = u₀, u = u₀+Δu, v = v₀, v = v₀+Δv cut out a plain rectangle S of area ΔuΔv. Nothing curved here — this is the easy domain we get to integrate over.',
      s: { size: 0.8, overlay: false, u0: 1.2, v0: 0.5 } },
    { t: 'T bends the four edges',
      n: 'The transformation x = u cos v, y = u sin v sends each straight edge of S to a coordinate curve: the u = const edges become circular arcs and the v = const edges become rays. The image R is a curved quadrilateral.',
      s: { size: 0.8, overlay: false, u0: 1.2, v0: 0.5 } },
    { t: 'Move S — the distortion is local',
      n: 'S has moved to another corner of the uv-plane (drag the big blue dots yourself). The same formula stretches the rectangle by a different amount depending on where it sits, so the area factor must be a function of (u,v), not a constant.',
      s: { size: 0.8, overlay: false, u0: 1.7, v0: 1.4 } },
    { t: 'Shrink S and the curves straighten',
      n: 'Pull Δu and Δv toward zero with the size slider. The panel keeps zooming in on R: the image stops looking curved and becomes a tiny parallelogram — the local behaviour of T is linear.',
      s: { size: 0.15, overlay: false, u0: 1.7, v0: 1.4 } },
    { t: 'The Jacobian is the area factor',
      n: 'Overlay the tangent vectors r_uΔu and r_vΔv at the image of (u₀,v₀). The parallelogram they span has area |∂(x,y)/∂(u,v)|ΔuΔv; the readout shows it matching the true area of R more and more exactly as the rectangle shrinks.',
      s: { size: 0.15, overlay: true, u0: 1.7, v0: 1.4 } },
    { t: 'Try your own transformation',
      n: 'Edit x(u,v) and y(u,v) — try x = u²−v², y = 2uv, or the shear x = u+v, y = v. Watch which maps preserve area (|J| = 1) and which blow it up or collapse it (|J| = 0).',
      s: { size: 0.6, overlay: true, u0: 1.2, v0: 0.5 } }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var s = steps[cur].s;
    st.u0 = s.u0; st.v0 = s.v0; st.du = s.size; st.dv = s.size; st.overlay = s.overlay;
    if (st.u0 + st.du > MAXU) st.u0 = MAXU - st.du;
    if (st.v0 + st.dv > MAXV) st.v0 = MAXV - st.dv;
    var sl = document.getElementById('shrinkRectangleInput');
    sl.value = s.size; document.getElementById('shrinkRectangleVal').value = s.size;
    document.getElementById('showParallelogramInput').checked = s.overlay;
    document.getElementById('demoNarration').innerHTML = '<b>' + steps[cur].t + '</b><br>' + steps[cur].n;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A change of variables T(u,v) = (x(u,v), y(u,v)) carries a small rectangle S in the uv-plane to a curved region R in the xy-plane, and the Jacobian determinant is the local factor by which the area is stretched.
KEY INSIGHT (what students should walk away understanding): A transformation is locally just a linear map, so an infinitesimal rectangle of area ΔuΔv becomes a parallelogram of area |∂(x,y)/∂(u,v)|ΔuΔv — the Jacobian is nothing more than that local area-stretching factor.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A change of variables T(u,v) = (x(u,v), y(u,v)) carries a small rectangle S in the uv-plane to a curved region R in the xy-plane, and the Jacobian determinant is the local factor by which the area is stretched.",
  "figureType": "diagram",
  "elements": [
    "Left panel: uv-plane with black u-axis (horizontal, arrowhead right) and v-axis (vertical, arrowhead up), axis labels 'u' and 'v'",
    "Left panel: two blue vertical grid lines labeled 'u = u₀' and 'u = u₀ + Δu', extending beyond the rectangle",
    "Left panel: two blue horizontal grid lines labeled 'v = v₀' and 'v = v₀ + Δv', extending beyond the rectangle",
    "Left panel: shaded light-blue rectangle S with blue outline, interior label 'S'",
    "Left panel: four blue corner dots at the intersections of the grid lines",
    "Left panel: corner label '(u₀, v₀)' at the lower-left corner",
    "Left panel: side-length labels 'Δu' (below bottom edge) and 'Δv' (right of right edge)",
    "Center: large curved pale-yellow/tan arrow with gray outline pointing from the left panel to the right panel, labeled 'T'",
    "Right panel: xy-plane with black x-axis and y-axis, axis labels 'x' and 'y'",
    "Right panel: curved quadrilateral region R, shaded light blue with thick blue boundary curves, interior label 'R'",
    "Right panel: four boundary-curve labels with leaders — 'Image of u = u₀', 'Image of u = u₀ + Δu', 'Image of v = v₀', 'Image of v = v₀ + Δv'",
    "Right panel: the four image curves extend slightly past the corners of R (as full coordinate curves)",
    "Optional overlay: tangent vectors r_u Δu and r_v Δv at the image of (u₀, v₀) with the dashed parallelogram they span",
