// @FIGURE_CODE_BEGIN
(function () {
  var W = 1120, H = 356;
  var BLUE = '#1a9ad7', FILL = '#cfe7f5', ORANGE = '#e2641e', INK = '#111';
  var SERIF = 'Georgia, "Times New Roman", serif';

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

  var gArrow = draw.group();
  var gLeft = draw.group();
  var gRight = draw.group();

  // uv-plane mapping (fixed)
  var SU = 150, OX = 72, OY = 292;
  var MAXU = 2.15, MAXV = 1.50, UMIN = 0.45, VMIN = 0.25;
  var st = { u0: 1.10, v0: 0.35, du: 0.8, dv: 0.8, overlay: false };
  var FX = null, FY = null;

  function UX(u) { return OX + u * SU; }
  function VY(v) { return OY - v * SU; }

  // ---------- helpers ----------
  function txt(g, s, x, y, size, opts) {
    opts = opts || {};
    var t = g.plain(s);
    t.font({
      family: opts.family || SERIF, size: size, style: opts.style || 'italic',
      weight: opts.weight || 'normal', anchor: opts.anchor || 'start'
    });
    t.attr({ x: x, y: y, fill: opts.fill || INK });
    t.attr({
      'paint-order': 'stroke', stroke: '#fff',
      'stroke-width': opts.halo == null ? 4.5 : opts.halo, 'stroke-linejoin': 'round'
    });
    return t;
  }
  function mkText(g, s, size, opts) {
    var t = txt(g, s, -6000, -6000, size, opts);
    var w = 0;
    try { w = t.node.getComputedTextLength(); } catch (e) { w = 0; }
    if (!w || !isFinite(w)) w = 0.5 * size * s.length;
    return { t: t, w: w, size: size };
  }
  function arrowHead(g, x, y, ang, L, color) {
    g.polygon([[x, y],
      [x - L * Math.cos(ang - 0.38), y - L * Math.sin(ang - 0.38)],
      [x - L * Math.cos(ang + 0.38), y - L * Math.sin(ang + 0.38)]]
      .map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color).stroke('none');
  }
  function vecArrow(g, x1, y1, x2, y2, color, width) {
    var a = Math.atan2(y2 - y1, x2 - x1), L = 12;
    g.line(x1, y1, x2 - 0.8 * L * Math.cos(a), y2 - 0.8 * L * Math.sin(a))
      .stroke({ color: color, width: width, linecap: 'round' });
    arrowHead(g, x2, y2, a, L, color);
  }
  function pstr(pts) { return pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '); }
  function fmt(n) { return (isFinite(n) ? (Math.abs(n) < 1e-4 ? 0 : n).toFixed(3) : '—'); }
  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

  // ---------- transition arrow (static) ----------
  (function () {
    var p = gArrow.path('M402,256 C432,208 468,182 500,172 L500,146 L550,193 L500,240 L500,216 ' +
      'C470,224 440,248 414,284 Z');
    p.fill('#fbe9c6').stroke({ color: '#9a9a9a', width: 2, linejoin: 'round' });
    p.css('cursor', 'pointer');
    p.on('mousemove', function (e) { showTooltip('T maps every point of the uv-plane to a point of the xy-plane', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The transformation T', 'T(u,v) = (x(u,v), y(u,v)) carries the flat rectangle S on the left to the curved region R on the right. Straight coordinate lines u = const and v = const become curved coordinate curves.');
      });
    txt(gArrow, 'T', 456, 168, 23, { anchor: 'middle', weight: 'bold', fill: '#7a6a3a' });
  })();

  // ---------- transformation sampling ----------
  function mapPt(u, v) { return [FX(u, v), FY(u, v)]; }
  function curvePts(fixedIsU, fixedVal, a, b, n) {
    var out = [];
    for (var i = 0; i <= n; i++) {
      var t = a + (b - a) * i / n;
      var p = fixedIsU ? mapPt(fixedVal, t) : mapPt(t, fixedVal);
      if (isFinite(p[0]) && isFinite(p[1])) out.push(p);
    }
    return out;
  }
  function regionPts(n) {
    var u0 = st.u0, v0 = st.v0, du = st.du, dv = st.dv, out = [], i, p;
    for (i = 0; i <= n; i++) { p = mapPt(u0 + du * i / n, v0); if (isFinite(p[0]) && isFinite(p[1])) out.push(p); }
    for (i = 1; i <= n; i++) { p = mapPt(u0 + du, v0 + dv * i / n); if (isFinite(p[0]) && isFinite(p[1])) out.push(p); }
    for (i = 1; i <= n; i++) { p = mapPt(u0 + du * (1 - i / n), v0 + dv); if (isFinite(p[0]) && isFinite(p[1])) out.push(p); }
    for (i = 1; i < n; i++) { p = mapPt(u0, v0 + dv * (1 - i / n)); if (isFinite(p[0]) && isFinite(p[1])) out.push(p); }
    return out;
  }
  function shoelace(pts) {
    var a = 0;
    for (var i = 0; i < pts.length; i++) {
      var j = (i + 1) % pts.length;
      a += pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1];
    }
    return Math.abs(a) / 2;
  }
  function centroid(pts) {
    var a = 0, cx = 0, cy = 0;
    for (var i = 0; i < pts.length; i++) {
      var j = (i + 1) % pts.length;
      var cr = pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1];
      a += cr; cx += (pts[i][0] + pts[j][0]) * cr; cy += (pts[i][1] + pts[j][1]) * cr;
    }
    if (Math.abs(a) < 1e-9) {
      var sx = 0, sy = 0;
      pts.forEach(function (p) { sx += p[0]; sy += p[1]; });
      return [sx / pts.length, sy / pts.length];
    }
    return [cx / (3 * a), cy / (3 * a)];
  }
  function partials(u, v) {
    var h = 1e-4;
    return {
      xu: (FX(u + h, v) - FX(u - h, v)) / (2 * h),
      yu: (FY(u + h, v) - FY(u - h, v)) / (2 * h),
      xv: (FX(u, v + h) - FX(u, v - h)) / (2 * h),
      yv: (FY(u, v + h) - FY(u, v - h)) / (2 * h)
    };
  }

  // ---------- left panel ----------
  var dragMode = null;
  function drawLeft() {
    var g = gLeft;
    var u0 = st.u0, v0 = st.v0, du = st.du, dv = st.dv;

    // axes
    g.line(24, OY, 414, OY).stroke({ color: '#000', width: 2 });
    arrowHead(g, 428, OY, 0, 13, '#000');
    g.line(OX, 344, OX, 46).stroke({ color: '#000', width: 2 });
    arrowHead(g, OX, 32, -Math.PI / 2, 13, '#000');
    txt(g, 'u', 388, OY - 15, 21, { anchor: 'middle' });
    txt(g, 'v', OX + 20, 50, 21, { anchor: 'middle' });

    var lx = UX(u0), rx = UX(u0 + du), by = VY(v0), ty = VY(v0 + dv);
    var extH = clamp(0.42 * du * SU, 48, 74);
    var extV = clamp(0.42 * dv * SU, 42, 70);
    var lineL = clamp(lx - extH, 90, 404);
    var lineR = clamp(rx + extH, 96, 404);
    var lineBot = clamp(by + extV, 60, 336);
    var lineTop = clamp(ty - extV, 58, 330);

    // blue coordinate lines
    [lx, rx].forEach(function (x) {
      g.line(x, lineBot, x, lineTop).stroke({ color: BLUE, width: 3.4, linecap: 'round' });
    });
    [by, ty].forEach(function (y) {
      g.line(lineL, y, lineR, y).stroke({ color: BLUE, width: 3.4, linecap: 'round' });
    });

    // rectangle S
    var rect = g.rect(Math.max(1, rx - lx), Math.max(1, by - ty)).move(lx, ty)
      .fill({ color: FILL, opacity: 0.95 }).stroke({ color: BLUE, width: 2 }).css('cursor', 'pointer');
    rect.on('mousemove', function (e) { showTooltip('S : the rectangle [u₀, u₀+Δu] × [v₀, v₀+Δv], area = ΔuΔv', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The rectangle S', 'In the uv-plane the region is a plain rectangle of area Δu·Δv = ' +
          fmt(st.du * st.dv) + '. Integrating over such a rectangle is easy — that is the whole reason for changing variables.');
      });

    // corner dots
    [[lx, by], [rx, by], [lx, ty], [rx, ty]].forEach(function (c) {
      g.circle(10).center(c[0], c[1]).fill(BLUE).stroke({ color: '#fff', width: 1 });
    });
    var hLL = g.circle(17).center(lx, by).fill(BLUE).stroke({ color: '#fff', width: 2 }).css('cursor', 'move');
    var hUR = g.circle(17).center(rx, ty).fill(BLUE).stroke({ color: '#fff', width: 2 }).css('cursor', 'nwse-resize');
    hLL.on('mousemove', function (e) { showTooltip('Drag: move S (changes u₀, v₀)', e); }).on('mouseleave', hideTooltip);
    hUR.on('mousemove', function (e) { showTooltip('Drag: resize S (changes Δu, Δv)', e); }).on('mouseleave', hideTooltip);
    hLL.on('mousedown', function (e) { e.preventDefault(); dragMode = 'll'; });
    hUR.on('mousedown', function (e) { e.preventDefault(); dragMode = 'ur'; });

    // interior label S (prominent, as in source)
    txt(g, 'S', (lx + rx) / 2, (ty + by) / 2 + 9, 26,
      { anchor: 'middle', weight: 'bold', halo: (rx - lx) > 46 ? 3 : 5 });

    // math labels
    var FS = 20;
    var narrow = (rx - lx) < 118, shortR = (by - ty) < 62;
    if (!narrow) {
      txt(g, 'u = u₀', lx, lineTop - 13, FS, { anchor: 'middle' });
      txt(g, 'u = u₀ + Δu', rx, lineTop - 13, FS, { anchor: 'middle' });
    } else {
      txt(g, 'u = u₀', lx - 8, lineTop - 13, FS, { anchor: 'end' });
      txt(g, 'u = u₀ + Δu', rx + 8, lineTop - 13, FS, { anchor: 'start' });
    }
    if (!shortR) {
      txt(g, 'v = v₀ + Δv', lineR + 12, ty + 7, FS, { anchor: 'start' });
      txt(g, 'v = v₀', lineR + 12, by + 7, FS, { anchor: 'start' });
    } else {
      txt(g, 'v = v₀ + Δv', lineR + 12, ty - 8, FS, { anchor: 'start' });
      txt(g, 'v = v₀', lineR + 12, by + 20, FS, { anchor: 'start' });
    }
    txt(g, '(u₀, v₀)', lx - 14, by + 32, FS, { anchor: 'end' });
    if (narrow) {
      txt(g, 'Δu', rx + 16, by + 34, FS, { anchor: 'start' });
    } else {
      txt(g, 'Δu', (lx + rx) / 2, by + 30, FS, { anchor: 'middle' });
    }
    if (shortR) {
      txt(g, 'Δv', rx + 14, ty - 26, FS, { anchor: 'start' });
    } else {
      txt(g, 'Δv', rx + 14, (ty + by) / 2 + 8, FS, { anchor: 'start' });
    }
  }

  // ---------- right panel ----------
  // fixed caption anchors, copied from the source layout
  var CAPS = [
    { key: 'u0', s: 'Image of u = u₀', x: 726, y: 62, anchor: 'end' },
    { key: 'u1', s: 'Image of u = u₀ + Δu', x: 736, y: 31, anchor: 'start' },
    { key: 'v1', s: 'Image of v = v₀ + Δv', x: 892, y: 133, anchor: 'start' },
    { key: 'v0', s: 'Image of v = v₀', x: 892, y: 249, anchor: 'start' }
  ];

  function drawRight() {
    var g = gRight;
    var u0 = st.u0, v0 = st.v0, du = st.du, dv = st.dv;
    var eu = 0.34 * du, ev = 0.34 * dv, N = 90;

    var cU0 = curvePts(true, u0, v0 - ev, v0 + dv + ev, N);
    var cU1 = curvePts(true, u0 + du, v0 - ev, v0 + dv + ev, N);
    var cV0 = curvePts(false, v0, u0 - eu, u0 + du + eu, N);
    var cV1 = curvePts(false, v0 + dv, u0 - eu, u0 + du + eu, N);
    var reg = regionPts(40);

    if (reg.length < 8 || cU0.length < 4) {
      txt(g, 'T is undefined on this rectangle', 800, 160, 19,
        { anchor: 'middle', style: 'normal', fill: '#c00' });
      return null;
    }

    // fit the REGION (not the extended curves) into a fixed, label-free box
    var minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    reg.forEach(function (p) {
      if (p[0] < minX) minX = p[0]; if (p[0] > maxX) maxX = p[0];
      if (p[1] < minY) minY = p[1]; if (p[1] > maxY) maxY = p[1];
    });
    var bw = Math.max(maxX - minX, 1e-6), bh = Math.max(maxY - minY, 1e-6);
    var X0 = 658, X1 = 884, Y0 = 78, Y1 = 224;
    var s = Math.min((X1 - X0) / bw, (Y1 - Y0) / bh);
    var mx = (minX + maxX) / 2, my = (minY + maxY) / 2;
    var cx = (X0 + X1) / 2, cy = (Y0 + Y1) / 2;
    function PX(x) { return cx + (x - mx) * s; }
    function PY(y) { return cy - (y - my) * s; }
    function SC(c) { return c.map(function (p) { return [PX(p[0]), PY(p[1])]; }); }

    // axes (follow the true origin when it is nearby, clamped clear of all labels)
    var axY = clamp(PY(0), 288, 306);
    var ayX = clamp(PX(0), 548, 602);
    var axH = g.line(536, axY, 1076, axY).stroke({ color: '#000', width: 2 });
    arrowHead(g, 1090, axY, 0, 13, '#000');
    var axV = g.line(ayX, 344, ayX, 46).stroke({ color: '#000', width: 2 });
    arrowHead(g, ayX, 32, -Math.PI / 2, 13, '#000');
    [axH, axV].forEach(function (a) {
      a.css('cursor', 'pointer').on('mousemove', function (e) {
        showTooltip('xy-axes; the view zooms so that R always fills the panel', e);
      }).on('mouseleave', hideTooltip);
    });
    txt(g, 'x', 1046, axY - 15, 21, { anchor: 'middle' });
    txt(g, 'y', ayX + 20, 52, 21, { anchor: 'middle' });

    // region R
    var scr = SC(reg);
    var trueArea = shoelace(reg);
    var poly = g.polygon(pstr(scr)).fill({ color: FILL, opacity: 0.95 }).stroke('none').css('cursor', 'pointer');
    poly.on('mousemove', function (e) { showTooltip('R = T(S), true area ≈ ' + fmt(trueArea), e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The image region R', 'R = T(S) is bounded by four coordinate curves. Its area is ' + fmt(trueArea) +
          ', while S has area ' + fmt(st.du * st.dv) + '. The ratio is the local area-stretching factor — the Jacobian.');
      });

    // boundary curves, drawn past the corners
    var curves = { u0: SC(cU0), u1: SC(cU1), v0: SC(cV0), v1: SC(cV1) };
    ['u0', 'u1', 'v0', 'v1'].forEach(function (k) {
      if (curves[k].length > 1) {
        g.polyline(pstr(curves[k])).fill('none')
          .stroke({ color: BLUE, width: 3.6, linecap: 'round', linejoin: 'round' });
      }
    });

    // interior label R (bold italic, prominent as in the source)
    var C = centroid(scr);
    txt(g, 'R', C[0], C[1] + 9, 26, { anchor: 'middle', weight: 'bold', halo: 3.5 });

    // captions at their source positions, with short leaders to their curves
    var labels = [];
    CAPS.forEach(function (cap) {
      var lbl = mkText(g, cap.s, 19, { anchor: cap.anchor, style: 'normal', halo: 5 });
      var tx = cap.x;
      if (cap.anchor === 'start') tx = Math.min(tx, 1112 - lbl.w);
      else tx = Math.max(tx, lbl.w + 8);
      var box = {
        x0: cap.anchor === 'start' ? tx : tx - lbl.w,
        x1: cap.anchor === 'start' ? tx + lbl.w : tx,
        y0: cap.y - 15, y1: cap.y + 5
      };
      // leader to the nearest point of the matching curve
      var c = curves[cap.key], best = null, bd = 1e9;
      var ax0 = (box.x0 + box.x1) / 2, ay0 = (box.y0 + box.y1) / 2;
      for (var i = 0; i < c.length; i++) {
        var d = Math.hypot(c[i][0] - ax0, c[i][1] - ay0);
        if (d < bd) { bd = d; best = c[i]; }
      }
      if (best) {
        var qx = clamp(best[0], box.x0 - 3, box.x1 + 3);
        var qy = clamp(best[1], box.y0 - 3, box.y1 + 3);
        var gap = Math.hypot(best[0] - qx, best[1] - qy);
        if (gap > 7 && gap < 190) {
          g.line(qx, qy, best[0], best[1]).stroke({ color: '#8d959c', width: 1.2, linecap: 'round' });
        }
      }
      lbl.t.attr({ x: tx, y: cap.y });
      labels.push(lbl.t);
    });
    labels.forEach(function (t) { t.front(); });

    // Jacobian / tangent parallelogram overlay
    var dP = partials(u0, v0);
    var J = dP.xu * dP.yv - dP.xv * dP.yu;
    var Pt = mapPt(u0, v0);
    if (st.overlay && isFinite(J) && isFinite(Pt[0]) && isFinite(Pt[1])) {
      var A = [dP.xu * du, dP.yu * du], B = [dP.xv * dv, dP.yv * dv];
      var p0 = [PX(Pt[0]), PY(Pt[1])];
      var pA = [PX(Pt[0] + A[0]), PY(Pt[1] + A[1])];
      var pB = [PX(Pt[0] + B[0]), PY(Pt[1] + B[1])];
      var pAB = [PX(Pt[0] + A[0] + B[0]), PY(Pt[1] + A[1] + B[1])];
      var par = g.polygon(pstr([p0, pA, pAB, pB])).fill({ color: ORANGE, opacity: 0.13 })
        .stroke({ color: ORANGE, width: 1.9, linejoin: 'round' })
        .attr('stroke-dasharray', '6,4').css('cursor', 'pointer');
      par.on('mousemove', function (e) { showTooltip('Tangent parallelogram: area = |J| ΔuΔv = ' + fmt(Math.abs(J) * du * dv), e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Linear approximation', 'Near (u₀,v₀), T behaves like its derivative: the edges of S map to the vectors r_uΔu and r_vΔv. The parallelogram they span has area |∂(x,y)/∂(u,v)|·ΔuΔv, and it matches area(R) ever more exactly as Δu, Δv → 0.');
        });
      vecArrow(g, p0[0], p0[1], pA[0], pA[1], ORANGE, 2.4);
      vecArrow(g, p0[0], p0[1], pB[0], pB[1], ORANGE, 2.4);
      g.circle(9).center(p0[0], p0[1]).fill(ORANGE);
      txt(g, 'rᵤΔu', pA[0] + (pA[0] >= p0[0] ? 10 : -10), pA[1] + (pA[1] >= p0[1] ? 18 : -8), 17,
        { anchor: pA[0] >= p0[0] ? 'start' : 'end', fill: ORANGE });
      txt(g, 'rᵥΔv', pB[0] + (pB[0] >= p0[0] ? 10 : -10), pB[1] + (pB[1] >= p0[1] ? 18 : -8), 17,
        { anchor: pB[0] >= p0[0] ? 'start' : 'end', fill: ORANGE });

      // readout strip, well below the x-axis
      var bx = 596, by2 = 312;
      g.rect(500, 42).move(bx, by2).fill('#ffffff').stroke({ color: '#c9ced4', width: 1 }).radius(4);
      var mono = { family: 'ui-monospace, Consolas, monospace', style: 'normal', halo: 0 };
      txt(g, 'Δu·Δv = ' + fmt(du * dv) + '      |J(u₀,v₀)| = ' + fmt(Math.abs(J)) +
        '      |J|·Δu·Δv = ' + fmt(Math.abs(J) * du * dv), bx + 12, by2 + 17, 13, mono);
      txt(g, 'area(R) = ' + fmt(trueArea) + '      |J|ΔuΔv / area(R) = ' +
        fmt(Math.abs(J) * du * dv / (trueArea || NaN)), bx + 12, by2 + 34, 13, mono);
    }
    return { J: J, trueArea: trueArea };
  }

  // ---------- render ----------
  function render() {
    if (!FX || !FY) return;
    gLeft.clear(); gRight.clear();
    drawLeft();
    var stats = drawRight();
    var el = document.getElementById('readout');
    if (el) {
      if (!stats) { el.innerHTML = 'T is undefined on this rectangle.'; }
      else {
        var a0 = st.du * st.dv, aJ = Math.abs(stats.J) * a0;
        el.innerHTML = 'Δu·Δv = ' + fmt(a0) + '<br>|J(u₀,v₀)| = ' + fmt(Math.abs(stats.J)) +
          '<br>|J|·Δu·Δv = ' + fmt(aJ) + '<br>area(R) = ' + fmt(stats.trueArea) +
          '<br>ratio = ' + fmt(aJ / (stats.trueArea || NaN));
      }
    }
  }

  // ---------- interactions ----------
  function fixBounds() {
    st.du = clamp(st.du, 0.05, MAXU - UMIN);
    st.dv = clamp(st.dv, 0.05, MAXV - VMIN);
    st.u0 = clamp(st.u0, UMIN, MAXU - st.du);
    st.v0 = clamp(st.v0, VMIN, MAXV - st.dv);
  }
  window.update_shrinkRectangle = function (v) { st.du = v; st.dv = v; fixBounds(); render(); };
  window.toggle_showParallelogram = function (on) { st.overlay = !!on; render(); };
  window.preset = function (a, b) {
    var xi = document.getElementById('xuvInput'), yi = document.getElementById('yuvInput');
    xi.value = a; xi.dispatchEvent(new Event('input'));
    yi.value = b; yi.dispatchEvent(new Event('input'));
  };

  // dragging on S
  function toUser(ev) {
    var pt = draw.node.createSVGPoint();
    pt.x = ev.clientX; pt.y = ev.clientY;
    var m = draw.node.getScreenCTM();
    if (!m) return null;
    return pt.matrixTransform(m.inverse());
  }
  document.addEventListener('mousemove', function (ev) {
    if (!dragMode) return;
    var p = toUser(ev); if (!p) return;
    var u = (p.x - OX) / SU, v = (OY - p.y) / SU;
    if (dragMode === 'll') {
      st.u0 = clamp(u, UMIN, MAXU - st.du);
      st.v0 = clamp(v, VMIN, MAXV - st.dv);
    } else {
      st.du = clamp(u - st.u0, 0.05, MAXU - st.u0);
      st.dv = clamp(v - st.v0, 0.05, MAXV - st.v0);
      var sl = document.getElementById('shrinkRectangleInput');
      sl.value = clamp(st.du, 0.05, 1.2).toFixed(2);
      document.getElementById('shrinkRectangleVal').value = (+sl.value).toFixed(2);
    }
    render();
  });
  document.addEventListener('mouseup', function () { dragMode = null; });

  // ---------- equations ----------
  bindEquationInput('xuvInput', function (fn) { FX = fn; render(); }, { variables: ['u', 'v'] });
  bindEquationInput('yuvInput', function (fn) { FY = fn; render(); }, { variables: ['u', 'v'] });

  // ---------- demo steps ----------
  var steps = [
    {
      t: 'The rectangle S in the uv-plane',
      n: 'On the left, the coordinate lines u = u₀, u = u₀+Δu, v = v₀, v = v₀+Δv cross and cut out a plain rectangle S of area ΔuΔv. Nothing curved here — this is the easy domain we get to integrate over.',
      s: { size: 0.8, overlay: false, u0: 1.10, v0: 0.35 }
    },
    {
      t: 'T bends all four edges',
      n: 'With x = u²−v², y = 2uv every straight edge of S becomes a coordinate curve: the u = const edges bow one way, the v = const edges the other, so R is a curved quadrilateral. Try the “polar” preset to get arcs and rays instead.',
      s: { size: 0.8, overlay: false, u0: 1.10, v0: 0.35 }
    },
    {
      t: 'Move S — the distortion is local',
      n: 'S has moved to another part of the uv-plane (drag the big blue dots yourself). The same formula stretches the rectangle by a different amount depending on where it sits, so the area factor must be a function of (u,v), not a constant.',
      s: { size: 0.8, overlay: false, u0: 1.30, v0: 0.62 }
    },
    {
      t: 'Shrink S and the curves straighten',
      n: 'Pull Δu and Δv toward zero with the size slider. The right panel keeps zooming in on R: the image stops looking curved and becomes a tiny parallelogram — the local behaviour of T is linear.',
      s: { size: 0.15, overlay: false, u0: 1.30, v0: 0.62 }
    },
    {
      t: 'The Jacobian is the area factor',
      n: 'Overlay the tangent vectors rᵤΔu and rᵥΔv at the image of (u₀,v₀). The parallelogram they span has area |∂(x,y)/∂(u,v)|ΔuΔv; the readout shows it matching the true area of R more and more exactly as the rectangle shrinks.',
      s: { size: 0.15, overlay: true, u0: 1.30, v0: 0.62 }
    },
    {
      t: 'Try your own transformation',
      n: 'Edit x(u,v) and y(u,v) — try polar x = u cos v, y = u sin v, or the shear x = u+v, y = v. Watch which maps preserve area (|J| = 1) and which blow it up or collapse it (|J| = 0).',
      s: { size: 0.6, overlay: true, u0: 1.10, v0: 0.35 }
    }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var s = steps[cur].s;
    st.u0 = s.u0; st.v0 = s.v0; st.du = s.size; st.dv = s.size; st.overlay = s.overlay;
    fixBounds();
    var sl = document.getElementById('shrinkRectangleInput');
    sl.value = s.size; document.getElementById('shrinkRectangleVal').value = s.size;
    document.getElementById('showParallelogramInput').checked = s.overlay;
    document.getElementById('demoNarration').innerHTML = '<b>' + steps[cur].t + '</b><br>' + steps[cur].n;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
